/* The real @nucleux/react scenes (nx-how.js, built from the site's React source) and their theme. */
kit.exec('nx-react.js');
kit.exec('nx-how.js');
kit.css(window.NXHow.css);

/* One stacked tile as on the site: copy left (a two-tone headline: lead in the
   tile's ink, accent in its color), the live scene right. Every tile sits at
   the same top, so a settled tile covers the one beneath whole (no edges
   showing, the user's choice). */
window.HWF = {
  TOP: [104, 104, 104],
  tile(kit, i, sceneT) {
    const T = window.NXHow.TILES[i];
    const el = kit.h('<div class="hw-tile hw-s' + i + '" style="top:' + window.HWF.TOP[i] + 'px">' +
      '<div class="hw-copy"><p class="hw-step">' + kit.esc(T.step) + '</p>' +
      '<h3 class="hw-title"><span class="hw-lead">' + kit.esc(T.lead) + '</span><span class="hw-accent">' + kit.esc(T.accent) + '</span></h3>' +
      '<p class="hw-body">' + kit.esc(T.body) + '</p></div>' +
      '<div class="hw-media"><div class="hw-canvas"></div></div><div class="hw-shade"></div></div>');
    kit.stage.append(el);
    /* each scene's own design canvas (the dashboard is drawn larger), scaled into the 960 px panel */
    const cv = el.querySelector('.hw-canvas'), c = window.NXHow.wideCanvas(T.id);
    cv.style.width = c.w + 'px';
    cv.style.height = c.h + 'px';
    cv.style.transform = 'scale(' + (960 / c.w) + ')';
    const scene = window.NXHow.mount(cv, T.id);
    if (sceneT != null) scene.render(sceneT);
    return { el, s: el.style, shade: el.querySelector('.hw-shade').style, scene };
  },
  /* a tile under the one rising over it: scale 1 to 0.97 from its top edge, a faint shade */
  cover(tile, p) {
    tile.s.transform = 'scale(' + (1 - 0.03 * p).toFixed(4) + ')';
    tile.shade.opacity = (0.035 * p).toFixed(4);
  },

  /* The NUCLEUX wordmark, as in the site's nav (index-new-concept.html): N U C L E
     in the word ink, U X in the cyan to violet gradient. `pre` keeps gradient ids
     unique per scene. The intro draws it and glides it into SLOT; every later
     scene keeps it there. */
  MARK: [
    'M2.30469 3.23047V19.8459H6.45853V9.69201L14.3047 19.8459H18.4585V3.23047H14.3047V13.3843L6.45853 3.23047H2.30469Z',
    'M20.7656 3.23047V14.3074C20.7656 18.3074 23.0733 20.3074 27.6887 20.3074C32.3041 20.3074 34.6118 18.3074 34.6118 14.3074V3.23047H30.4579V13.8459C30.4579 15.692 29.5349 16.6151 27.6887 16.6151C25.8425 16.6151 24.9195 15.692 24.9195 13.8459V3.23047H20.7656Z',
    'M38.0781 11.5382C38.0781 5.9997 40.5397 3.23047 45.4627 3.23047H51.9243V6.92278H46.155C43.5397 6.92278 42.232 8.46124 42.232 11.5382C42.232 14.6151 43.5397 16.1535 46.155 16.1535H51.9243V19.8459H45.4627C40.5397 19.8459 38.0781 17.0766 38.0781 11.5382Z',
    'M54.2344 3.23047V19.8459H65.7728V16.1535H58.3882V3.23047H54.2344Z',
    'M68.0781 3.23047V19.8459H80.7704V16.1535H72.232V13.1535H79.8474V9.92278H72.232V6.92278H80.7704V3.23047H68.0781Z',
    'M83.5391 3V14.0769C83.5391 18.0769 85.8468 20.0769 90.4621 20.0769C95.0775 20.0769 97.3852 18.0769 97.3852 14.0769V3H93.2314V13.6154C93.2314 15.4615 92.3083 16.3846 90.4621 16.3846C88.616 16.3846 87.6929 15.4615 87.6929 13.6154V3H83.5391Z',
    'M99.6959 3H104.773L108.465 8.53846L112.157 3H117.696L112.157 11.3077L117.696 19.6154H112.157L108.465 14.0769L104.773 19.6154H99.2344L105.234 11.3077L99.6959 3Z',
  ],
  WORD: '#0A0A0A',
  SLOT: { x: 100, y: 36, w: 168 },
  markSvg(pre) {
    const fill = (i) => (i < 5 ? window.HWF.WORD : 'url(#' + pre + '-g' + (i - 5) + ')');
    const grad = (n) => '<linearGradient id="' + pre + '-g' + n + '" x1="84" y1="10.5" x2="118" y2="10" gradientUnits="userSpaceOnUse">' +
      '<stop stop-color="#21A4D7"/><stop offset="0.975962" stop-color="#8B57C7"/></linearGradient>';
    return '<svg viewBox="0 0 120 24" fill="none" aria-hidden="true" style="display:block;width:100%;height:auto;overflow:visible">' +
      window.HWF.MARK.map((d, i) => '<path d="' + d + '" fill="' + fill(i) + '" pathLength="1"/>').join('') +
      '<defs>' + grad(0) + grad(1) + '</defs></svg>';
  },
  /* the wordmark resting in its slot */
  mark(kit, pre) {
    const S = window.HWF.SLOT;
    kit.stage.append(kit.h('<div style="position:absolute;left:' + S.x + 'px;top:' + S.y + 'px;width:' + S.w + 'px">' + window.HWF.markSvg(pre) + '</div>'));
  },
};
